import { Kpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';

export const REPORT_TYPE = {
  TOTAL: 'TOTAL',
  BEER_ADJ: 'BEER_ADJ',
} as const;

export type ReportType = (typeof REPORT_TYPE)[keyof typeof REPORT_TYPE];

const KPI_USES_TOP_BOTTOM_REPORT_TYPE = new Set<Kpi>([
  'volume',
  'nr',
  'cores',
  'power',
]);

export const kpiUsesTopBottomReportType = (kpi: Kpi): boolean =>
  KPI_USES_TOP_BOTTOM_REPORT_TYPE.has(kpi);
